// Content with portions generated by generative AI platform
package org.eclipse.kura.internal.rest.auth.jwt;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.time.Duration;
import java.time.Instant;

import org.eclipse.kura.KuraAuthenticationFailedException;
import org.junit.Test;

public class RefreshTokenFamilyEvictionTest {

    private static final Instant PAST = Instant.now().minus(Duration.ofSeconds(1));
    private static final Instant FUTURE = Instant.now().plus(Duration.ofMinutes(1));

    private final RefreshTokenFamilies families = new RefreshTokenFamilies();
    private String familyId;
    private KuraAuthenticationFailedException failure;

    @Test
    public void aFamilyIsForgottenOnceItsTrackingDeadlinePasses() {
        givenAFamilyTrackedUntil(PAST);

        whenTheFamilyIsAdvancedFrom(0);

        thenTheAdvanceIsRefused();
    }

    @Test
    public void advancingAFamilyMovesItsTrackingDeadline() {
        givenAFamilyTrackedUntil(FUTURE);
        givenTheFamilyWasAdvancedFrom(0, PAST);

        whenTheFamilyIsAdvancedFrom(1);

        thenTheAdvanceIsRefused();
    }

    private void givenAFamilyTrackedUntil(final Instant trackedUntil) {
        this.familyId = this.families.start(trackedUntil);
    }

    private void givenTheFamilyWasAdvancedFrom(final long generation, final Instant trackedUntil) {
        advance(generation, trackedUntil);

        assertNull(this.failure);
    }

    private void whenTheFamilyIsAdvancedFrom(final long generation) {
        advance(generation, FUTURE);
    }

    private void thenTheAdvanceIsRefused() {
        assertNotNull(this.failure);
    }

    private void advance(final long generation, final Instant trackedUntil) {
        try {
            this.families.advance(this.familyId, generation, trackedUntil);
        } catch (final KuraAuthenticationFailedException e) {
            this.failure = e;
        }
    }
}
